import fs from 'fs';
import path from 'path';
import { MODULE_ROOT, ROOT_FILES, moduleDirs } from './project-layout.js';
import { toPosix, listSnapshotPaths } from './snapshot.js';
import { fatal } from '../utils/logger.js';

/**
 * Maps module paths (relative to the module root, with `.js`, e.g.
 * `handlers/message.js`) to their on-disk location under the module root.
 */

/** On-disk path (OS separators) of a module path. */
export function wdPath(modulePath) {
  return path.join(MODULE_ROOT, ...toPosix(modulePath).split('/'));
}

/** Project-root-relative POSIX path of a module path, for output. */
export function displayPath(modulePath) {
  return `${MODULE_ROOT}/${toPosix(modulePath)}`;
}

/** Normalize a user-typed target to a module path: POSIX separators, leading `tgcloud/` stripped. */
export function toModulePath(input) {
  const p = toPosix(String(input));
  const prefix = `${MODULE_ROOT}/`;
  return p.startsWith(prefix) ? p.slice(prefix.length) : p;
}

export function existsWd(modulePath) {
  return fs.existsSync(wdPath(modulePath));
}

export function readWd(modulePath) {
  return fs.readFileSync(wdPath(modulePath), 'utf-8');
}

/** Write a module file, creating its parent directories (incl. the module root). */
export function writeWd(modulePath, content) {
  const full = wdPath(modulePath);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content);
}

export function unlinkWd(modulePath) {
  const full = wdPath(modulePath);
  if (fs.existsSync(full)) fs.unlinkSync(full);
}

/**
 * Root-level entries of a pre-0.2.0 layout (modules at the project root, no
 * populated module root); empty when the layout is current. A root module
 * directory counts only when a root file exists or the snapshot has modules.
 */
export function findLegacyEntries() {
  const isDir = (p) => { try { return fs.statSync(p).isDirectory(); } catch { return false; } };
  const isFile = (p) => { try { return fs.statSync(p).isFile(); } catch { return false; } };
  const names = [...ROOT_FILES, ...moduleDirs()];
  const populated = names.some((n) => fs.existsSync(path.join(MODULE_ROOT, n)));
  if (populated) return [];
  const rootFiles = ROOT_FILES.filter(isFile);
  const dirs = moduleDirs().filter(isDir).map((d) => `${d}/`);
  if (!rootFiles.length && !listSnapshotPaths().length) return [];
  return [...rootFiles, ...dirs];
}

/** Fatal for a pre-0.2.0 layout; points at `tgcloud upgrade`. */
export function requireCurrentLayout() {
  const legacy = findLegacyEntries();
  if (!legacy.length) return;
  fatal(
    `Legacy project layout (modules at the project root: ${legacy.join(', ')}).\n` +
    `  Run "tgcloud upgrade" to move them into ${MODULE_ROOT}/.`
  );
}
